    function __ESBMC_assume(bool) internal pure {}

    function run(uint sendValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendValue)); require(sendValue <= 1000000000000000000000000000000);
        require(sendValue == 10);
        require(address(this).balance >= sendValue);
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        c.play{value: sendValue}(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        assert(potAfter == potBefore + sendValue || potAfter == 0);
    }

    receive() external payable {}
